<script setup>
import {ref,computed,onMounted,onUnmounted,watch} from 'vue';
import ReadToolbar from './ReadToolbar.vue';
import ChecklistGroups from './ChecklistGroups.vue';
import {useChecklistRoleDrag} from './checklist-role-drag.js';
import {groupChecklistRows} from './checklist-groups.js';
import MailRewardList from './MailRewardList.vue';
import DojoIcon from './DojoIcon.vue';
import {compareResources,resourceClass,resourceTypes,resourceTypeOf,resourceHighlighted} from './dojo/resource-presentation.js';
import './dojo/resource-style.css';
import {mailSource,mailTypeLabel} from './dojo/mail-source.js';
import {summarizeMails,groupMails} from './dojo/statistics.js';
import DojoReport from './DojoReport.vue';
const reportOpen=ref(false),reportRef=ref(null);
import BlueTickets from './BlueTickets.vue';
const archive=ref(false),archiveRef=ref(null),participants=ref(false),selected=ref([]),roles=ref([]),rows=ref([]),revision=ref(null),busy=ref(false),error=ref(''),view=ref('daily'),month=ref(''),role=ref(''),source=ref('all');
const archiveGroups=ref([{id:'',name:'未分组',collapsed:false}]),groupEditing=ref(false),groupSaving=ref(false),roleSearch=ref('');
const roleDrag=useChecklistRoleDrag(groupAction);
const resourceRoles=computed(()=>groupChecklistRows(archiveGroups.value,roles.value.filter(r=>r.selected||rows.value.some(row=>row.role_id===r.id))).flatMap(g=>g.rows));
const filteredResourceRoles=computed(()=>resourceRoles.value.filter(r=>!roleSearch.value.trim()||(r.label+' '+r.server).toLowerCase().includes(roleSearch.value.trim().toLowerCase())));
const groupedResourceRoles=computed(()=>groupChecklistRows(archiveGroups.value,filteredResourceRoles.value,r=>r,true));
const editableArchiveRoles=computed(()=>roles.value.map(r=>({...r,key:r.id,name:r.label})));
function applyArchives(value){roles.value=value.roles;archiveGroups.value=value.groups?.length?value.groups:[{id:'',name:'未分组',collapsed:false}];revision.value=value.revision}
async function groupAction(payload){
 if(busy.value||groupSaving.value)return false;
 groupSaving.value=true;error.value='';
 try{const response=await window.pywebview.api.blue_mail('groups',payload);if(!response.ok)throw Error(response.error);applyArchives(response.data);return true}
 catch(e){error.value=e.message||'分组调整未能保存';return false}
 finally{groupSaving.value=false}
}
function chooseResourceRole(event,id){if(roleDrag.click(event))role.value=id}
function toggleResourceGroup(event,group){if(roleDrag.click(event))groupAction({action:'toggle',id:group.id,collapsed:!group.collapsed})}
function moveResourceGroup(group,delta){const order=archiveGroups.value,index=order.findIndex(g=>g.id===group.id),other=order[index+delta];if(other)groupAction({action:'group_move',id:group.id,before:other.id,after:delta>0})}
watch([view,resourceRoles],()=>{if(['daily','calendar'].includes(view.value)&&!resourceRoles.value.some(r=>r.id===role.value))role.value=resourceRoles.value[0]?.id||''},{immediate:true});
const compareItems=compareResources;
function sortedMailItems(row){return [...row.items].sort((a,b)=>compareItems({id:a[0],n:a[1],...label(a[0])},{id:b[0],n:b[1],...label(b[0])}))}
const localDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=localDate(new Date());
month.value=today.slice(0,7);
function shift(date,n){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+n);return localDate(d)}
function monday(date){const d=new Date(date+'T12:00:00');return shift(date,-((d.getDay()+6)%7))}
const weekStart=ref(monday(today)),weekPage=ref(0),weekCap=ref(3),weekBox=ref(null),resource=ref(''),resourceType=ref('all'),detail=ref(null);
function matchesResource(id){return (!resource.value||String(id)===resource.value)&&(resourceType.value==='all'||resourceTypeOf({id,...label(id)})===resourceType.value)}
const baseRows=computed(()=>rows.value.filter(r=>(!role.value||r.role_id===role.value)&&(source.value==='all'||mailSource(r)===source.value)).map(row=>({...row,items:row.items.filter(([id])=>matchesResource(id))})).filter(row=>row.items.length));
const weekDates=computed(()=>Array.from({length:7},(_,i)=>shift(weekStart.value,i)));
const shownRoles=computed(()=>roles.value.filter(r=>(r.selected||rows.value.some(m=>m.role_id===r.id))&&(!role.value||r.id===role.value)));
const weekRoles=computed(()=>shownRoles.value.slice(weekPage.value*weekCap.value,(weekPage.value+1)*weekCap.value));
const maxPage=computed(()=>Math.max(1,Math.ceil(shownRoles.value.length/weekCap.value)));
function resources(list){const map=new Map();for(const row of list)for(const [id,n] of row.items)map.set(id,(map.get(id)||0)+n);return [...map].map(([id,n])=>({id,n,...label(id)})).sort(compareItems);}
const resourceOptions=computed(()=>resources(rows.value).filter(item=>resourceType.value==='all'||resourceTypeOf(item)===resourceType.value));
watch(resourceType,()=>{resource.value='';statsPage.value=0});
function dayMails(id,date){return baseRows.value.filter(r=>r.role_id===id&&r.date===date)}
function dayItems(id,date){return resources(dayMails(id,date)).filter(r=>!resource.value||String(r.id)===resource.value)}
function calendarItems(id,date){return dayItems(id,date).filter(item=>resourceHighlighted(item.id))}
function weekItems(id){return resources(baseRows.value.filter(r=>r.role_id===id&&r.date>=weekStart.value&&r.date<=weekDates.value[6])).filter(r=>!resource.value||String(r.id)===resource.value)}
function dailyResourceGroups(items){return resourceTypes.map(type=>({...type,items:items.filter(item=>resourceTypeOf(item)===type.id)})).filter(type=>type.items.length)}
function itemText(r){return r.name+(r.stars?` ${r.stars}星`:'')+' × '+r.n.toLocaleString('zh-CN')}
const calendarMonth=computed(()=>month.value||today.slice(0,7));
const calendarMails=computed(()=>baseRows.value.filter(row=>row.role_id===role.value&&row.date.startsWith(calendarMonth.value)));
const calendarRecordDates=computed(()=>[...new Set(calendarMails.value.map(row=>row.date))].sort((a,b)=>b.localeCompare(a)));
const calendarMonthItems=computed(()=>resources(calendarMails.value).filter(item=>item.n>0));
const calendarHarvestItems=computed(()=>{
 const keys=[{id:490001,name:'蓝票'},{id:434111,name:'黑碎'},{id:411,name:'黑蛋'}].map(key=>{const item=calendarMonthItems.value.find(item=>Number(item.id)===key.id);return item?{...item,name:key.name}:null}).filter(Boolean);
 return [...keys,...calendarMonthItems.value.filter(item=>!resourceHighlighted(item.id))];
});
const calendarDays=computed(()=>{const first=calendarMonth.value+'-01';const d=new Date(first+'T12:00:00');const offset=(d.getDay()+6)%7;const end=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();return [...Array(offset).fill(null),...Array.from({length:end},(_,i)=>shift(first,i))]});
const detailRows=computed(()=>detail.value?dayMails(detail.value.id,detail.value.date):[]);

function openDay(id,date){detail.value={id,date,label:roles.value.find(r=>r.id===id)?.label||'历史角色'}}
let observer;
onMounted(()=>{observer=new ResizeObserver(entries=>{if(view.value!=='week')return;const h=weekBox.value?.querySelector('.dojo-week-wrap')?.clientHeight||entries[0].contentRect.height;weekCap.value=Math.max(1,Math.floor((h-66)/112));});if(weekBox.value)observer.observe(weekBox.value)});
onUnmounted(()=>observer?.disconnect());
watch([weekBox,view],()=>{if(weekBox.value)observer?.observe(weekBox.value)});
watch([role,weekCap],()=>{weekPage.value=0});
watch(month,()=>{weekPage.value=0;if(month.value)weekStart.value=monday(month.value+'-01')});
watch(shownRoles,()=>{weekPage.value=Math.min(weekPage.value,maxPage.value-1)},{immediate:true});
const filtered=computed(()=>view.value==='stats'?statsRows.value:baseRows.value.filter(r=>view.value==='week'?(r.date>=weekStart.value&&r.date<=weekDates.value[6]):(!month.value||r.date.startsWith(month.value))));
const catalog=computed(()=>Object.assign({},...rows.value.map(r=>r.item_meta||{})));
const names=computed(()=>Object.assign({},...rows.value.map(r=>r.item_names||{})));
function label(id){const info=catalog.value[id]||{};return {name:info.name||names.value[id]||'名称待识别',stars:info.stars||null,card:info.kind==='realm_card'||(info.name||names.value[id])==='太阴符咒'}}
const totals=computed(()=>{const m=new Map();for(const r of filtered.value)for(const [id,n] of r.items)m.set(id,(m.get(id)||0)+n);return [...m].map(([id,n])=>({id,n,...label(id)})).filter(r=>!resource.value||String(r.id)===resource.value).sort(compareItems);});
const days=computed(()=>{const m=new Map();for(const r of filtered.value){const key=r.role_id+'|'+r.date;if(!m.has(key))m.set(key,{key,date:r.date,label:r.label,count:0,items:new Map()});const d=m.get(key);d.count++;for(const [id,n] of r.items)d.items.set(id,(d.items.get(id)||0)+n);}return [...m.values()].sort((a,b)=>b.date.localeCompare(a.date)).map(d=>({...d,items:[...d.items].map(([id,n])=>({id,n,...label(id)})).filter(r=>!resource.value||String(r.id)===resource.value).sort(compareItems)}));});
const enrolled=computed(()=>roles.value.filter(r=>r.selected&&r.active).length);
const countRoles=computed(()=>new Set(filtered.value.map(r=>r.role_id)).size);
const statsRange=ref('all'),statsGroup=ref('role'),statsFrom=ref(today.slice(0,7)+'-01'),statsTo=ref(today),statsPage=ref(0),statsAverage=ref(false);
const statsInvalid=computed(()=>statsRange.value==='custom'&&(!statsFrom.value||!statsTo.value||statsFrom.value>statsTo.value));
const statsRows=computed(()=>{
  if(statsInvalid.value)return [];
  return baseRows.value.filter(row=>statsRange.value==='month'?row.date.startsWith(month.value||today.slice(0,7)):statsRange.value==='custom'?row.date>=statsFrom.value&&row.date<=statsTo.value:true);
});
const statsSummary=computed(()=>summarizeMails(statsRows.value));
const statsEntries=computed(()=>groupMails(statsRows.value,statsGroup.value));
const statsPages=computed(()=>Math.max(1,Math.ceil(statsEntries.value.length/10)));
const statsVisible=computed(()=>statsEntries.value.slice(statsPage.value*10,statsPage.value*10+10));
const statsColumns=computed(()=>resources(statsRows.value).filter(item=>!resource.value||String(item.id)===resource.value));
watch([statsRange,statsGroup,statsFrom,statsTo,month,role,resource,rows],()=>{statsPage.value=0});
function statsAmount(entry,id){
  const value=entry.amounts[String(id)]||0;
  return (statsAverage.value&&entry.roleDayCount?value/entry.roleDayCount:value).toLocaleString('zh-CN',{maximumFractionDigits:statsAverage.value?2:0});
}
async function refresh(){busy.value=true;error.value='';try{const a=await window.pywebview.api.blue_mail('archives');if(!a.ok)throw Error(a.error);applyArchives(a.data);const b=await window.pywebview.api.blue_mail('records');if(!b.ok)throw Error(b.error);rows.value=b.data.filter(r=>r.type!==400175);}catch(e){error.value=e.message}finally{busy.value=false}}
function choose(){selected.value=roles.value.filter(r=>r.selected&&r.active).map(r=>r.id);participants.value=true}
async function saveSubjects(){busy.value=true;error.value='';try{const r=await window.pywebview.api.blue_records('subjects',{ids:selected.value,revision:revision.value});if(!r.ok)throw Error(r.error);applyArchives(r.data);participants.value=false;}catch(e){error.value=e.message}finally{busy.value=false}}
async function exportCsv(){busy.value=true;error.value='';try{const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const data=[['角色','日期（北京时间）','奖励类型','资源名称','星级','数量']];for(const r of filtered.value)for(const [id,n] of r.items){if(resource.value&&String(id)!==resource.value)continue;const x=label(id);data.push([r.label,r.date,mailTypeLabel(r),x.name,x.stars??(x.card?'待识别':''),n]);}const r=await window.pywebview.api.blue_export({kind:'csv',filename:'资源记录.csv',content:data.map(r=>r.map(cell).join(',')).join('\r\n')});if(!r.ok)throw Error(r.error)}catch(e){error.value=e.message}finally{busy.value=false}}
const readWindows=ref([]),readWindowKey=ref(''),readMessage=ref(''),readWarnings=ref([]);
async function loadReadWindows(){const response=await window.pywebview.api.blue_mail('list');if(!response.ok)throw Error(response.error);readWindows.value=response.data;if(!readWindows.value.some(w=>String(w.pid)===readWindowKey.value))readWindowKey.value=String(readWindows.value[0]?.pid||'')}
async function refreshReadControls(){if(groupSaving.value)return;await refresh();try{await loadReadWindows()}catch(e){error.value=e.message}}
const currentReadRole=computed(()=>role.value);
async function readResources(all,currentRole=''){
 if(busy.value||groupSaving.value)return;
 const win=readWindows.value.find(w=>String(w.pid)===readWindowKey.value);
 if(!all&&!currentRole&&!win){error.value='请先选择游戏窗口';return}
 busy.value=true;error.value='';readMessage.value='正在读取…';readWarnings.value=[];
 try{
  const archive=await window.pywebview.api.blue_mail('archives');if(!archive.ok)throw Error(archive.error);
  const result=await window.pywebview.api.blue_mail(all?'read_all':currentRole?'read_role':'read',all?{revision:archive.data.revision,confirm:true}:currentRole?{role_id:currentRole,revision:archive.data.revision,confirm:true}:{...win,revision:archive.data.revision,confirm:true});
  if(!result.ok)throw Error(result.error);
  const value=result.data;
  readMessage.value=all?`读取完成 · 成功 ${value.succeeded||0} 个窗口 · 失败 ${value.failed||0} 个 · 新增 ${value.added||0} 封邮件`:`读取完成 · 新增 ${value.added||0} 封 · 跳过重复 ${value.duplicates||0} 封`;
  readWarnings.value=all?(value.results||[]).flatMap(row=>[...(row.warnings||[]),...(row.ok?row.loaded_count?[]:[(row.label||'游戏窗口')+'：暂未读到邮件，不代表零产出']:[(row.label||'游戏窗口')+'：'+row.error])]):[...(value.warnings||[]),...(value.loaded_count?[]:['暂未读到邮件，不代表零产出'])];
  await refresh();
 }catch(e){error.value=e.message;readMessage.value='读取未完成'}finally{busy.value=false}
}
function canLeave(){if(groupSaving.value)return false;groupEditing.value=false;if(reportOpen.value&&reportRef.value?.canLeave()===false)return false;reportOpen.value=false;detail.value=null;if(busy.value)return false;if(archive.value&&archiveRef.value?.canLeave()===false)return false;return true}defineExpose({canLeave});onMounted(refreshReadControls);
</script>
<template><div class="dojo-page workspace-page" v-if="!archive"><header class="dojo-header workspace-header"><div><h1>资源记录</h1><p>每场收获，按角色归档</p></div><ReadToolbar :windows="readWindows" v-model="readWindowKey" :busy="busy||groupSaving" @refresh="refreshReadControls" @read="readResources(false)" @all="readResources(true)"><template #current><button :disabled="busy||groupSaving||!currentReadRole" @click="readResources(false,currentReadRole)">读取当前角色</button></template></ReadToolbar></header><div v-if="readMessage" class="resource-read-status"><span role="status">{{readMessage}}</span><details v-if="readWarnings.length"><summary>查看详情 · {{readWarnings.length}}</summary><p v-for="(warning,index) in readWarnings" :key="index">{{warning}}</p></details></div><p class="dojo-error" v-if="error" role="alert">{{error}}</p><section class="dojo-filter workspace-filters"><label>月份<input aria-label="产出月份" type="month" v-model="month"></label><button @click="month=''">全部日期</button><label>角色<select aria-label="产出角色" v-model="role"><option v-if="!['daily','calendar'].includes(view)" value="">全部角色</option><option v-else-if="!resourceRoles.length" value="" disabled>暂无角色</option><template v-for="g in groupChecklistRows(archiveGroups,resourceRoles)" :key="g.id"><optgroup v-if="g.showHeader" :label="g.name"><option v-for="r in g.rows" :key="r.id" :value="r.id">{{r.label}} · {{r.server}}</option></optgroup><template v-else><option v-for="r in g.rows" :key="r.id" :value="r.id">{{r.label}} · {{r.server}}</option></template></template></select></label><label>奖励来源<select aria-label="奖励来源" v-model="source"><option value="all">全部来源</option><option value="dojo">道馆</option><option value="xiajian">狭间暗域</option></select></label><label>资源类型<select aria-label="资源类型" v-model="resourceType"><option value="all">全部类型</option><option v-for="type in resourceTypes" :key="type.id" :value="type.id">{{type.label}}</option></select></label><label>显示资源<select aria-label="显示资源" v-model="resource"><option value="">全部资源</option><option :class="resourceClass(r.id)" v-for="r in resourceOptions" :key="r.id" :value="String(r.id)">{{r.name}}{{r.stars?' · '+r.stars+'星':''}}</option></select></label><span>记录保存在本机</span></section><div class="dojo-summary"><span><b>{{countRoles}}</b> 个角色</span><span><b>{{filtered.length}}</b> 封奖励邮件</span><span><b>{{totals.length}}</b> 种资源</span><small>结界卡按星级统计</small></div><section class="dojo-panel" :class="{'dojo-panel-calendar':view==='calendar'}"><nav class="dojo-tabs" aria-label="产出视图"><button v-for="t in [{id:'daily',name:'角色日报'},{id:'calendar',name:'月历'},{id:'detail',name:'邮件明细'},{id:'stats',name:'统计'}]" :key="t.id" :aria-pressed="view===t.id" :class="{active:view===t.id}" @click="view=t.id">{{t.name}}</button><small>邮件发送日即战斗日</small><div class="dojo-view-actions"><button @click="groupEditing=true" :disabled="busy||groupSaving">分组管理</button><button @click="reportOpen=true" :disabled="busy">周报 / 月报</button><details class="dojo-more"><summary>更多</summary><div><button @click="exportCsv" :disabled="busy||!filtered.length">导出 CSV</button><button class="dojo-link" @click="archive=true">旧蓝票记录</button></div></details></div></nav><div class="dojo-week" v-if="view==='week'" ref="weekBox"><div class="dojo-week-tools"><b>{{weekStart}} — {{weekDates[6]}}</b><div><button @click="weekStart=shift(weekStart,-7)">上一周</button><button @click="weekStart=monday(today)">本周</button><button @click="weekStart=shift(weekStart,7)">下一周</button></div></div><div class="dojo-week-wrap"><table class="dojo-week-table"><thead><tr><th>角色 / 日期</th><th v-for="(date,i) in weekDates" :key="date">{{['周一','周二','周三','周四','周五','周六','周日'][i]}}<small>{{date.slice(5)}}</small></th><th>一周合计</th></tr></thead><tbody><tr v-for="r in weekRoles" :key="r.id"><th>{{r.label}}<small>{{r.server}}</small></th><td v-for="date in weekDates" :key="date"><button class="dojo-day-cell" :data-date="date" :class="{recorded:dayMails(r.id,date).length}" @click="openDay(r.id,date)" :title="dayItems(r.id,date).map(itemText).join('；')"><template v-if="dayMails(r.id,date).length"><span :class="resourceClass(item.id)" v-for="item in dayItems(r.id,date).slice(0,3)" :key="item.id"><i>{{item.name}}{{item.stars?' '+item.stars+'星':''}}</i><b>{{item.n.toLocaleString('zh-CN')}}</b></span><small>{{dayMails(r.id,date).length}} 封{{dayItems(r.id,date).length>3?' · 查看全部':''}}{{!dayItems(r.id,date).length?' · 无该资源':''}}</small></template><span class="dojo-unread" v-else>未记录</span></button></td><td><div class="dojo-week-total" :title="weekItems(r.id).map(itemText).join('；')"><span :class="resourceClass(item.id)" v-for="item in weekItems(r.id).slice(0,3)" :key="item.id">{{itemText(item)}}</span><small v-if="weekItems(r.id).length>3">更多资源见明细</small><span v-if="!weekItems(r.id).length">—</span></div></td></tr><tr v-if="!weekRoles.length"><td colspan="9" class="dojo-empty">先选择参与角色，再读取游戏邮件。</td></tr></tbody></table></div><footer class="dojo-week-pager"><span>共 {{shownRoles.length}} 个角色 · 第 {{weekPage+1}} / {{maxPage}} 页</span><div><button :disabled="!weekPage" @click="weekPage--">上一页</button><button :disabled="weekPage>=maxPage-1" @click="weekPage++">下一页</button></div></footer></div>
<div class="dojo-calendar" v-else-if="view==='calendar'"><div class="calendar-body"><section class="calendar-date-card" aria-label="角色月历"><div class="dojo-week-tools calendar-heading"><b>{{calendarMonth}} · {{roles.find(r=>r.id===role)?.label||'个人月历'}}</b><span>绿色日期有邮件记录 · 点击查看完整奖励</span></div><div class="dojo-calendar-grid" :style="{'--rows':Math.ceil(calendarDays.length/7)}"><strong v-for="day in ['周一','周二','周三','周四','周五','周六','周日']" :key="day">{{day}}</strong><template v-for="(date,index) in calendarDays" :key="index"><div v-if="!date"></div><button v-else class="dojo-calendar-cell" :data-date="date" :disabled="!role" :class="{recorded:dayMails(role,date).length,today:date===today,future:date>today}" @click="openDay(role,date)" :aria-label="date+' · '+(dayMails(role,date).length?dayMails(role,date).length+' 封邮件，查看奖励':'未记录')" :title="calendarItems(role,date).map(itemText).join('；')||'暂无关键奖励记录'"><b>{{Number(date.slice(-2))}}</b><span class="dojo-calendar-rewards" v-if="calendarItems(role,date).length"><span class="dojo-calendar-reward" :class="resourceClass(r.id)" v-for="r in calendarItems(role,date)" :key="r.id" :title="itemText(r)"><DojoIcon :id="r.id" /><span v-if="r.stars" class="dojo-calendar-star">{{r.stars}}星</span><b>{{r.n.toLocaleString('zh-CN')}}</b></span></span><small>{{dayMails(role,date).length?dayMails(role,date).length+' 封':''}}</small></button></template></div></section><aside class="calendar-month-summary" aria-label="当月收获汇总"><div class="calendar-summary-heading"><h3>当月收获</h3><span>{{calendarRecordDates.length}} 个记录日 · {{calendarMails.length}} 封邮件</span></div><div class="calendar-harvest-items" aria-label="当月道具收获" v-if="calendarHarvestItems.length"><div v-for="item in calendarHarvestItems" :key="item.id" class="calendar-harvest-item" :class="resourceClass(item.id)" :title="itemText(item)"><DojoIcon :id="item.id" /><span>{{item.name}}<small v-if="item.stars">{{item.stars}} 星</small></span><b>{{item.n.toLocaleString('zh-CN')}}</b></div></div><p clas