ay-resources b,.dojo-day-cards b{font-size:17px;font-variant-numeric:tabular-nums}.dojo-day-cards{border-top:1px dashed #e0d3bc;margin-top:15px;padding-top:13px;display:flex;align-items:center;flex-wrap:wrap;gap:12px}.dojo-day-cards>span{font-size:12px;color:#927f62}.dojo-day-cards>div{display:flex;align-items:center;gap:7px;padding:7px 10px;background:#f5efdf;border-radius:5px}.dojo-day-cards i{font-style:normal;color:#a27a37;margin-left:5px}.dojo-day-cards b{margin-left:12px}.dojo-scroll:has(.dojo-daily-layout){overflow:hidden}@media(max-width:1200px){.dojo-daily-layout{grid-template-columns:145px minmax(0,1fr);gap:12px}.dojo-day-resources{gap:8px 16px}}

/* Warm paper surfaces and restrained green accents match the desktop workspace. */
.dojo-page{gap:12px;padding:24px;background:#f5f1e8;box-sizing:border-box;color:#443e34}
.dojo-header h1{font-size:24px;letter-spacing:.5px}.dojo-header p{color:#95856f;font-size:12px;margin-top:4px}
.dojo-actions{gap:7px}.dojo-page button{transition:background .15s,border-color .15s;min-height:34px}
.dojo-page button:hover:not(:disabled){background:#f0e8d9;border-color:#c6b190}
.dojo-page .dojo-primary{background:#466452;border-color:#466452;color:#fffdf6}
.dojo-page .dojo-primary:hover:not(:disabled){background:#395642;border-color:#395642}
.dojo-filter{background:#ede7da;border-color:transparent;border-radius:10px;gap:10px 16px;padding:12px 16px}
.dojo-filter label{color:#8b775d;font-size:11px}.dojo-filter input,.dojo-filter select{background:#fffcf5;border-color:#dcd0bb;border-radius:7px}
.dojo-summary{display:flex;align-items:center;gap:22px;font-size:12px;padding:0 4px;color:#94836a;flex-shrink:0}
