.dojo-summary small{margin-left:auto;font-size:11px;color:#a19179}
.dojo-panel{border-color:#e3dac9;border-radius:12px;padding:16px;background:#fcf9f2;box-shadow:0 3px 14px #65513306}
.dojo-tabs{gap:4px;padding-bottom:12px}.dojo-tabs button{border:0;background:transparent;border-radius:7px;padding:7px 15px;color:#938169}
.dojo-tabs button.active{background:#e5eddf;color:#405d43;font-weight:600;box-shadow:inset 0 0 0 1px #d2dfca}
.dojo-tabs small{color:#a19179;font-size:11px}
.dojo-daily-layout{grid-template-columns:190px minmax(0,1fr);gap:18px}
.dojo-role-list{background:#f1ecdf;border:0;border-radius:9px;padding:8px;gap:4px;scrollbar-gutter:stable}
.dojo-role-list button{border:1px solid transparent;border-left:3px solid transparent;border-radius:7px;padding:10px 12px;min-height:44px}
.dojo-role-list button.active{background:#fffcf5;border-color:#e0d8c7;border-left-color:#638066;color:#415c43;box-shadow:0 2px 5px #62543808}
.dojo-role-list b{font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dojo-role-list small{font-size:11px;color:#a18c6c;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dojo-day-ledger{padding-right:5px;scrollbar-gutter:stable}
.dojo-day-card{border-color:#e6ddcc;border-radius:11px;background:#fffdf7;padding:18px 20px;margin-bottom:14px;box-shadow:0 2px 8px #59462604}
.dojo-day-card>header{padding-bottom:12px;margin-bottom:14px;border-color:#eee6d7}
.dojo-day-card header b{font-size:17px;font-weight:600;color:#4a5444}.dojo-day-card header span{font-size:12px;color:#a08c6f;margin-top:3px}
.dojo-day-card header button{font-size:11px;padding:5px 10px;background:#f7f2e7;border-color:#e8dfce}
.dojo-day-resources{grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:8px 12px}
.dojo-day-resources>div{background:#f7f3e9;border-radius:8px;padding:10px 13px;min-height:44px;box-sizing:border-box}
.dojo-day-resources>div>span{font-size:13px;color:#837055;min-width:0}.dojo-day-resources b{font-size:20px;font-weight:600;color:#4c5f48;white-space:nowrap}
.dojo-day-cards{border-color:#e5dbc6;margin-top:16px;gap:8px;padding-top:12px}.dojo-day-cards>span{flex-basis:100%;font-size:11px;color:#9c8969}
.dojo-day-cards>div{background:#efe9dc;border-radius:7px;padding:8px 11px;font-size:12px}.dojo-day-cards b{font-size:16px;color:#61533b}




.dojo-calendar-grid{gap:7px}.dojo-page button.dojo-calendar-cell{border-color:#e4dbca;background:#f8f4ea;border-radius:7px;padding:8px}
.dojo-page button.dojo-calendar-cell.recorded{background:#edf1e3;border-color:#d6dfc9}.dojo-calendar-cell>b{color:#78654a}
.dojo-calendar-grid>strong{color:#a28c6c}.dojo-scroll table th{color:#8e795b;font-size:12px}.dojo-scroll table td{font-size:13px}
.dojo-chip{background:#f2ecdf;border-radius:5px}
@media(max-width:1200px){.dojo-page{padding:16px;gap:10px}.dojo-daily-layout{grid-template-columns:155px minmax(0,1fr);gap:12px}.dojo-summary{gap:14px}.dojo-day-card{padding:15px}.dojo-day-resources{grid-template-columns:repeat(2,minmax(0,1fr))}.dojo-day-resources>div{padding:8px 10px}.dojo-day-resources b{font-size:17px}}

.dojo-subject-mask .dojo-mail-dialog{width:min(1180px,calc(100vw - 64px));max-width:none;box-sizing:border-box;max-height:85vh;display:flex;flex-direction:column;overflow:hidden;background:#fffcf5;border-radius:12px}
